(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0023.js"] = [{"id":"glyph-seal-7242","script":"seal","character":"牂","reading":"zāng","description":"牂zāng母羊。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牂"},{"id":"glyph-seal-7247","script":"seal","character":"片","reading":"piàn；piān","description":"piàn：(1)平而薄的物体卡～。名～。\n(2)切削成薄的形状～肉片。\n(3)少，零星～段（整体当中的一段）。～刻。～面。～甲不存。\n(4)指较大地区内划分的较小地区分～儿开会。\n(5)量词，指面积、范围、景象、心意等或成片的东西两～药。一～新气象。\n〔～假（jiǎ）名〕日本文所用的楷书字母。\npiān：义同（一），用于相片儿”、电影片儿”等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-片"},{"id":"glyph-seal-7248","script":"seal","character":"版","reading":"bǎn","description":"bǎn：(1)上面有文字或图形的用木板或金属等制成供印刷用的东西木～书。活字～。底～。修～。\n(2)印刷物排印一次（可多次印刷）及有关的事物排～。再～。～本。出～。～权。\n(3)报纸的一面头～头条重大新闻。\n(4)打土墙用的夹板～筑（筑土墙）。\n(5)户籍～图（原指户籍和地图，现泛指国家疆域，如我国～～辽阔”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-版"},{"id":"glyph-seal-724d","script":"seal","character":"牍","reading":"dú","description":"引申为公文\n无丝竹之乱耳,无案牍之\n①古代书写用的木片。\n②文件；书信文～、尺～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牍"},{"id":"glyph-seal-7252","script":"seal","character":"牒","reading":"dié","description":"dié：文书，证件通～。度～。尺～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牒"},{"id":"glyph-seal-7256","script":"seal","character":"牖","reading":"yǒu","description":"yǒu：窗户～户。蓬～茅椽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牖"},{"id":"glyph-seal-7259","script":"seal","character":"牙","reading":"yá","description":"yá：(1)齿（古代把大齿称为牙”，现在牙”是齿的通称，亦称牙齿”）～垢。～龈。～碜。～祭。\n(2)像牙齿形状的东西抽屉～子。\n(3)特指象牙～雕。\n(4)旧时介绍买卖从中取利的人～商。～行。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牙"},{"id":"glyph-seal-725b","script":"seal","character":"牛","reading":"niú","description":"niú：(1)哺乳动物，趾端有蹄，头上长一对角，是反刍类动物，力量很大，能耕田拉车，肉和奶可食，角、皮、骨可作器物～刀小试（喻有很大的本领，先在小事情上施展一下）。～黄。～角。\n(2)星名，二十八宿之～斗（指牛宿和斗宿二星）。\n(3)喻固执或骄傲～气。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牛"},{"id":"glyph-seal-725d","script":"seal","character":"牝","reading":"pìn","description":"pìn：(1)雌性的鸟或兽，与牡”相对～牛。～马。～鸡。\n(2)锁孔。\n(3)溪谷丘陵为牡，溪谷为～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牝"},{"id":"glyph-seal-725f","script":"seal","character":"牟","reading":"móu；mù","description":"móu：(1)取，谋求～利。\n(2)牛叫声～然而鸣”。\n(3)古同眸”，瞳人。\n(4)古同侔”，等同。\n(5)姓。\nmù：〔～平〕地名，在中国山东省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牟"},{"id":"glyph-seal-7261","script":"seal","character":"牡","reading":"mǔ","description":"mǔ：(1)雄性的鸟或兽，亦指植物的雄株，与牝”相对～牛。\n(2)锁匙～钥。\n(3)丘陵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牡"},{"id":"glyph-seal-7262","script":"seal","character":"牢","reading":"láo","description":"láo：(1)养牲畜的圈（juàn）虎～。亡羊补～（喻事后补救还不为迟）。～笼。\n(2)古代称作祭品的牲畜太～（古代帝王、诸侯祭祀社稷时，牛、羊、豕三牲全备之称）。少～（诸侯宗庙，用羊、豕之称）。\n(3)监禁犯人的地方监～。坐～。\n(4)结实，坚固，固定～固。～稳（a.稳妥可靠；b.物体稳定，不摇晃）。～记。～不可破。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牢"},{"id":"glyph-seal-7266","script":"seal","character":"牦","reading":"máo","description":"máo：〔～牛〕一种牛，全身有长毛，腿短。中国青藏高原地区出产，当地人民用来拉犁和驮运货物。肉和乳都可食用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牦"},{"id":"glyph-seal-7267","script":"seal","character":"牧","reading":"mù","description":"mù：(1)放养牲口～童。畜～。～场。放～。游～。～民。～歌。～群。\n(2)治～民（治理人民）。\n(3)古代治民之官州～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牧"},{"id":"glyph-seal-7269","script":"seal","character":"物","reading":"wù","description":"wù：(1)人以外的具体的东西事～。生～。～体。货～。礼～。文～。～价。～质。地大～博。～极必反。\n(2)内容，实质言之有～。\n(3)指自己以外的人或跟自己相对的环境～议（群众的批评）。待人接～。～望所归（众望所归）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-物"},{"id":"glyph-seal-726f","script":"seal","character":"牯","reading":"gǔ","description":"gǔ：母牛；亦指阄割后的公牛；亦泛指牛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牯"},{"id":"glyph-seal-7272","script":"seal","character":"牲","reading":"shēng","description":"shēng：(1)家畜～口。～灵。～畜。\n(2)古代特指供宴飨祭祀用的牛、羊、猪三～。献～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牲"},{"id":"glyph-seal-7275","script":"seal","character":"牵","reading":"qiān","description":"⒈拉,挽着,挽引向前～牛。手～手。～着向前走。\n⒉连带，带累～连。～累。～制。～一发而动全身。\n⒊惦念，缠连～肠挂肚。意惹情～。\n⒋拘束，拘泥～于所闻。\n牵qiàn 1.挽船的绳索。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牵"},{"id":"glyph-seal-7279","script":"seal","character":"特","reading":"tè","description":"tè：(1)不平常的，超出一般的～殊。～色。～产。～权。～性。～征。～需。～技。～务。～区。～价。～例。～效。\n(2)单，单一～为（wèi）。～设。～地。～惠。～辑。～使。～赦。～约。\n(3)只，但不～如此。相如度秦王～以诈佯为予赵城，实不可得”。\n(4)三岁的兽，一说四岁的兽不狩不猎，胡瞻尔庭有悬～兮！”\n(5)公牛，亦用以借指公马和雄性的牲畜。\n(6)配偶，匹配不因旧姻，求尔新～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-特"},{"id":"glyph-seal-727a","script":"seal","character":"牺","reading":"xī","description":"⒈〈古〉作祭品用的纯毛色的牲畜。\n①〈古〉祭祀用的牲畜，色纯的叫牺，体全的叫牲。〈喻〉为正义事业而舍弃生命英勇～牲。为有～牲多壮志。\n②泛指舍弃～牲休息时间。\n牺suō 1.酒樽名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-牺"},{"id":"glyph-seal-7280","script":"seal","character":"犀","reading":"xī","description":"xī：(1)哺乳动物，形状略像牛，皮粗而厚，多皱纹。角生在鼻上，产于印度一带的只生一只角，产于非洲的有两只角，可做器物，亦可入药（通称犀牛”）～角。～甲。～照。灵～。\n(2)坚固～舟（坚固的船）。～利（锐利；锋利）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犀"},{"id":"glyph-seal-728a","script":"seal","character":"犊","reading":"dú","description":"泛指牛\n犊车\n犊牧采薪\n犊子\n犊 dú牛犊；小牛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犊"},{"id":"glyph-seal-728d","script":"seal","character":"犍","reading":"jiān；qián","description":"jiān：公牛，特指骟去睾丸的公牛。\nqián：〔～为（wéi）〕地名，在中国四川省。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犍"},{"id":"glyph-seal-72ac","script":"seal","character":"犬","reading":"quǎn","description":"quǎn：狗猎～。警～。～马之劳。～牙交错。～子（谦辞，对人称自己的儿子）。桀～吠尧（喻走狗一心为主子效劳）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犬"},{"id":"glyph-seal-72af","script":"seal","character":"犯","reading":"fàn","description":"fàn：(1)抵触，违反～规。～法。～罪。～颜（旧时指冒犯君王或尊长的威严）。～讳。\n(2)违反法律的人，有罪的人～人。罪～。\n(3)侵害，进攻侵～。秋毫无～。\n(4)触发，发作～病。～愁。～疑。\n(5)做错事情～错误。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犯"},{"id":"glyph-seal-72b6","script":"seal","character":"状","reading":"zhuàng","description":"情形;状况\n⒈样子，形态，情形～态。～况。形～。喜笑～。重病～。\n⒋诉讼～纸。告～。\n⒌特殊格式的凭证。指嘉奖、委任等奖～。委任～。军令～。\n居首位的人养鸡～元。种菜～元。\n语。状语后有时要用助词\"地\"，如\"非常地激烈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-状"},{"id":"glyph-seal-72b7","script":"seal","character":"犷","reading":"guǎng","description":"粗野\n强悍,强壮凶悍\n年十五,犷悍\n犷jǐng 1.觉悟貌。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犷"},{"id":"glyph-seal-72b9","script":"seal","character":"犹","reading":"yóu","description":"兽名★属,也叫犹猢”,形如麂\n犬子\n如同∶比\n此犹文轩之与敝舆。╠\n⒈一种猿类动物～猢。\n⒉如，同，好像～如。过～不及。虽死～生。\n⒊还，尚且记忆～新。困兽～斗。\n犹yáo 1.摇动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-犹"},{"id":"glyph-seal-72c2","script":"seal","character":"狂","reading":"kuáng","description":"kuáng：(1)本称狗发疯，后亦指人精神失常～犬。疯～。癫～。发～。～人。\n(2)纵情任性或放荡骄恣的态度轻～。～妄（极端自高自大）。～吠（狗狂叫，借指疯狂的叫嚣）。～乱。～野。～躁。～恣。～草（草书的一种，风格狂放无羁）。\n(3)气势猛烈，超出常度～风。～飙。～热。力挽～澜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狂"},{"id":"glyph-seal-72c4","script":"seal","character":"狄","reading":"dí","description":"dí：(1)中国古族名。春秋前，长期活动于齐、鲁、晋、卫、宋、郑等国之间，与诸国有频繁的接触。因为他们主要居住于北方，故又通称北狄”（亦作翟”）。\n(2)秦汉以后，中国对北方少数民族的统称。\n(3)古代最下级的官吏。\n(4)有力的麋鹿。\n(5)古同翟”，乐舞所用的雉羽。\n(6)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狄"},{"id":"glyph-seal-72ce","script":"seal","character":"狎","reading":"xiá","description":"xiá：(1)亲近而态度不庄重～侮。～弄。～昵。～客（嫖客）。\n(2)习惯。\n(3)更替。\n(4)拥挤车骑并～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狎"},{"id":"glyph-seal-72d0","script":"seal","character":"狐","reading":"hú","description":"hú：(1)哺乳动物的一属，形状略像狼。毛赤黄色，性狡猾多疑，遇见攻击时肛门放出臭气，乘机逃跑。皮可做衣服（通称狐狸”）～臭（腋下臭气）。～肷（狐腋下和腹部的毛皮）。～疑（多疑）。～媚（曲意逢迎，投入所好）。～死首丘（传说狐狸将死，头必向出生的山丘。喻不忘本，亦喻对故乡的思念）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狐"},{"id":"glyph-seal-72d7","script":"seal","character":"狗","reading":"gǒu","description":"gǒu：哺乳动物，种类很多，听觉嗅觉都很敏锐，善于看守门户，有的可以训练成军犬、警犬走～。～彘（狗和猪）。～刨（páo）（一种游泳动作）。～盗（小偷）。～腿子。～仗人势。～尾续貂（喻拿粗劣的东西接到美好的东西后面，很不相称，常指文章）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狗"},{"id":"glyph-seal-72d9","script":"seal","character":"狙","reading":"jū；jv","description":"jū：(1)古书上说的一种猴子。\n(2)窥伺～伺（暗中窥伺）。～剌（伺人不备，突然行刺）。～诈（诡诈）。～击（伺人不备，突然袭击）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狙"},{"id":"glyph-seal-72e0","script":"seal","character":"狠","reading":"hěn","description":"hěn：(1)凶恶，残忍心～。～戾。～毒。～心。凶～。\n(2)勉强地抑制住难过的心情～着心把泪止住。\n(3)严厉地～批他一顿。\n(4)全力以赴～劲。～抓学习。\n(5)同很”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狠"},{"id":"glyph-seal-72e1","script":"seal","character":"狡","reading":"jiǎo","description":"jiǎo：(1)诡诈～猾。～诈。～黠。～辩。～赖。\n(2)多力，壮健壮～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狡"},{"id":"glyph-seal-72e9","script":"seal","character":"狩","reading":"shòu","description":"shòu：(1)打猎，古代指冬天打猎～猎。冬～。\n(2)古代指放火烧山以围猎。\n(3)古同守”，指帝王视察诸侯所守的地方。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狩"},{"id":"glyph-seal-72ec","script":"seal","character":"独","reading":"dú","description":"不见秘书心若失,百年衰病独登台","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-独"},{"id":"glyph-seal-72ef","script":"seal","character":"狯","reading":"kuài","description":"狡猾，狡诈，如狡狯。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-72f1","script":"seal","character":"狱","reading":"yù","description":"讼案\n⒈监牢，监禁罪犯的场所监～。入～。\n⒉官司，罪案有～。冤～。文字～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狱"},{"id":"glyph-seal-72f7","script":"seal","character":"狷","reading":"juàn","description":"juàn：(1)胸襟狭窄，性情急躁～急。～狭。\n(2)洁身自好，性情耿直～介。～傲。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狷"},{"id":"glyph-seal-72f8","script":"seal","character":"狸","reading":"lí","description":"lí：(1)即貉”。\n(2)哺乳动物，形状与猫相似，毛皮可制衣物。亦称狸子”、狸猫”、山猫”、豹猫”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狸"},{"id":"glyph-seal-72fc","script":"seal","character":"狼","reading":"láng","description":"láng：哺乳动物，形状很像狗，性残忍而贪婪，昼伏夜出，能伤害人畜。毛皮可制衣褥～狈。～奔豕突。～吞虎咽。～子野心（喻凶恶残暴的人的狂妄欲望和狠毒用心）。引～入室（喻引进坏人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-狼"},{"id":"glyph-seal-7303","script":"seal","character":"猃","reading":"xiǎn","description":"长嘴的狗\n载猃歇骄\n猃狁\n黄头黑犬\n猃狁，玭狁\n⒈〈古〉指一种长嘴的狗。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猃"},{"id":"glyph-seal-730e","script":"seal","character":"猎","reading":"liè","description":"⒈捕捉禽兽打～。～获。～鸡。\n⒉打猎的～人。～枪。\n猎xī 1.见\"猎猎\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猎"},{"id":"glyph-seal-7317","script":"seal","character":"猗","reading":"yī；yǐ","description":"yǐ：(1)叹词，表示赞美～～（美盛的样子）。～嗟。～舆。～靡（a.随风飘动的样子；b.婉顺的样子）。\n(2)文言助词，用如兮”，相当于啊”河水清且涟～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猗"},{"id":"glyph-seal-731b","script":"seal","character":"猛","reading":"měng","description":"měng：(1)气势大，力量大～将。～士。～烈。勇～。\n(2)忽然，突然～然。～省（xǐng）（亦作猛醒”）。～可（突然，陡然）。～不防。\n(3)严厉宽以济～。\n(4)凶暴苛政～于虎。～禽。～兽。～戾。～悍。\n(5)古哺乳动物，长毛的象～犸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猛"},{"id":"glyph-seal-731c","script":"seal","character":"猜","reading":"cāi","description":"cāi：(1)推测，推想～测。～断。～透。～中（zhòng）。～想。～度（duó）。\n(2)疑心，嫌疑～疑。～忌。～嫌。～拳（饮酒时助兴的游戏。亦称划拳”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猜"},{"id":"glyph-seal-731d","script":"seal","character":"猝","reading":"cù","description":"cù：突然～然。～尔。～生变化。～不及防。～死（突然发生的非暴力死亡）。～故（突然发生的事变）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猝"},{"id":"glyph-seal-7325","script":"seal","character":"猥","reading":"wěi","description":"wěi：(1)众，多。\n(2)琐碎烦杂～滥。～杂。\n(3)苟且然窃恨足下不深惟其终始，而～随俗之毁誉也”。\n(4)鄙陋，下流卑～。～亵。～劣。\n(5)谦辞，犹言辱先帝不以臣卑鄙，～自枉屈，三顾臣于草庐之中”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猥"},{"id":"glyph-seal-7329","script":"seal","character":"猩","reading":"xīng","description":"xīng：〔～～〕哺乳动物，猿类，毛赤褐色，前肢长，无尾，吃野果。产于南洋群岛的森林中。简称猩”，如～红”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猩"},{"id":"glyph-seal-732a","script":"seal","character":"猪","reading":"zhū","description":"zhū：(1)哺乳动物，肉可食，鬃可制刷，皮可制革，粪是很好的肥料～倌。～场。～圈（juàn）。～肉。生～。野～。种（zhǒng）～。\n(2)古同潴”，水积存之处。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猪"},{"id":"glyph-seal-732b","script":"seal","character":"猫","reading":"māo；máo","description":"māo：(1)哺乳动物，面呈圆形，脚有利爪，行动敏捷，会捉老鼠。\n(2)方言，躲藏。\nmáo：〔～腰〕弯腰。亦称毛腰”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猫"},{"id":"glyph-seal-732e","script":"seal","character":"献","reading":"xiàn","description":"下对上、卑对尊的进献\n有献于\n⒉表演，出主意～技。～殷勤。～计～策。\n献suō 1.古代一种滤酒方法。 2.雕刻。参见\"献豆\"。 3.通\"犠\"。古代酒器名。参见\"献尊\"。\n献xī 1.勺子;勺形之物。\n献yí 1.效法;模拟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-献"},{"id":"glyph-seal-7334","script":"seal","character":"猴","reading":"hóu","description":"hóu：(1)哺乳动物，种类很多，行动灵活，好群居～子。猿～。～戏。～头。～拳。～枣（中医指猕猴内脏的结石）。\n(2)喻机灵的人～儿精。\n(3)方言，乖巧，机敏（多指孩子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猴"},{"id":"glyph-seal-733f","script":"seal","character":"猿","reading":"yuán","description":"yuán：哺乳动物，与猴相似，比猴大，颊下没有囊，没有尾巴，猩猩、大猩猩、长臂猿等都是～猴。～人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-猿"},{"id":"glyph-seal-7350","script":"seal","character":"獐","reading":"zhāng","description":"zhāng：哺乳动物，形状像鹿，毛较粗，头上无角，雄的有长牙露出嘴外。皮可制革（亦称牙獐”）～头鼠目（形容相貌丑陋而神情狡猾）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-獐"},{"id":"glyph-seal-7352","script":"seal","character":"獒","reading":"áo","description":"áo：一种凶猛的狗，身体大，善斗，能帮助人打猎。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-獒"},{"id":"glyph-seal-7360","script":"seal","character":"獠","reading":"liáo","description":"liáo：(1)面貌凶恶～面。～牙（露在嘴外面的长牙）。\n(2)夜间打猎于是乃相与～于蕙圃”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-獠"},{"id":"glyph-seal-736d","script":"seal","character":"獭","reading":"tǎ","description":"几种水栖的食鱼鼬科动物的任一种,主要属于几乎全世界都有分布的水獭属\n獭祭\n獭tǎ水獭，受保护的哺乳动物，禁止捕杀。水獭头宽扁，尾巴长，脚短趾间有蹼。穴居水边捕食鱼类。毛深褐色，皮毛珍贵，可做衣、帽等。獭肝可供药用。另有海～、旱～等\n，皮毛也都珍贵。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-獭"},{"id":"glyph-seal-737e","script":"seal","character":"獾","reading":"huān","description":"huān：哺乳动物，毛灰色，善掘土，穴居山野，昼伏夜出。毛可制笔，毛皮可制裘，其脂肪熬炼的獾油可治疗烫伤等。亦称狗獾”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-獾"},{"id":"glyph-seal-7384","script":"seal","character":"玄","reading":"xuán","description":"xuán：(1)深奥不容易理解的～妙。～奥。～理（a.深奥的道理；b.魏晋玄学所标榜的道理）。～学。～秘。\n(2)虚伪，不真实，不可靠～想。～虚。\n(3)黑色～青（深黑色）。～武（a.道教所奉的北方之神，它的形象为龟蛇合体；b.二十八宿中北方七宿的合称）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玄"},{"id":"glyph-seal-7387","script":"seal","character":"率","reading":"lǜ；shuài","description":"shuài：(1)带领～领。统～。～队。～先（带头）。～兽食人（喻暴君残害人民）。\n(2)轻易地，不细想，不慎重轻～。草～。～尔。～尔操觚（觚”，供写书用的木简；意思是轻易地下笔作文）。\n(3)爽直坦白直～。坦～。\n(4)大概，大略～常。大～。\n(5)遵循～教。～礼。\n(6)模范，楷模表～。\n(7)漂亮，俏皮（亦作帅”）这字写得～。\n(8)姓。\nlǜ：比值，两数之比效～。税～。概～。圆周～。出勤～。增长～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-率"},{"id":"glyph-seal-7389","script":"seal","character":"玉","reading":"yù","description":"yù：(1)石头的一种，质细而坚硬，有光泽，略透明，可雕琢成工艺品～石。～器。～玺（君主的玉印）。抛砖引～。金～良言。～不琢，不成器。\n(2)美，尊贵的，敬辞～泉。～液（美酒）。～言。～姿。～照（敬称别人的照片）。～宇（a.天空；b.瑰丽的宫阙殿宇）。亭亭～立。金科～律。金～其外，败絮其中。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玉"},{"id":"glyph-seal-738b","script":"seal","character":"王","reading":"wáng；wàng","description":"wáng：(1)古代一国君主的称号，现代有些国家仍用这种称号～国。～法。公子～孙。～朝（cháo）。\n(2)中国古代皇帝以下的最高爵位～公。～侯。\n(3)一族或一类中的首领山大～。蜂～。～牌（桥牌中最大的牌；喻最有力的人物或手段）。\n(4)大～父（祖父）。～母（祖母）。\n(5)姓。\nwàng：古代指统治者谓以仁义取得天下～天下。～此大邦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-王"},{"id":"glyph-seal-738e","script":"seal","character":"玎","reading":"dīng","description":"dīng：〔～玲〕象声词，多形容玉石撞击声。\n〔～当〕象声词，形容金属、磁器等撞击声。亦作丁当”、叮当”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玎"},{"id":"glyph-seal-7391","script":"seal","character":"玑","reading":"jī","description":"玑衡,古代的一种天文仪器\n⒈不圆的珠子。\n⒉〈古〉观测天文的仪器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玑"},{"id":"glyph-seal-7395","script":"seal","character":"玕","reading":"gān","description":"见“琅玕”，古代指形状像珠子的美玉。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7396","script":"seal","character":"玖","reading":"jiǔ","description":"jiǔ：(1)似玉的黑色石。\n(2)九”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玖"},{"id":"glyph-seal-7399","script":"seal","character":"玙","reading":"yú","description":"玉不雕,玙?","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玙"},{"id":"glyph-seal-73a0","script":"seal","character":"玠","reading":"náo","description":"玠náo 1.亦作\"玪\"。同\"猱\"。兽名，猿属。 2.亦作\"玪\"。见\"玠人\"。 3.通\"扰\"。乱，惊乱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玠"},{"id":"glyph-seal-73a6","script":"seal","character":"玦","reading":"jué","description":"jué：(1)半环形有缺口的佩玉，古代常用以赠人表示决绝绝人以～。\n(2)戴于右拇指助拉弓弦之器。俗称扳指”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玦"},{"id":"glyph-seal-73a9","script":"seal","character":"玩","reading":"wán","description":"wán：(1)游戏～耍。～笑。～兴（xìng）。～具。～偶。\n(2)戏弄，搬弄～弄。～狎。～花招儿。\n(3)观赏～赏。～味。瞻～。～物丧志。\n(4)可供观赏的东西古～。\n(5)轻视，忽视～忽职守。～世不恭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玩"},{"id":"glyph-seal-73ad","script":"seal","character":"玭","reading":"xiǎn","description":"玭xiǎn 1.见\"玭狁\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玭"},{"id":"glyph-seal-73af","script":"seal","character":"环","reading":"huán","description":"泛指圆圈形的物品\n⒈玉圈她手上带有碧～。\n⒉圈形的东西门～。滚铁～。\n⒊围绕～绕。群山～抱。～顾周围。\n⒋射击、射箭时击中环靶的环数中十～。\n环huàn 1.击退，使退却。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-环"},{"id":"glyph-seal-73b2","script":"seal","character":"玲","reading":"líng","description":"líng：形容玉碰击的声音～～作响。～～盈耳。～珑（a.金玉碰击声，如和銮～～”；b.形容器物细致精巧，如小巧～～”；c.形容人的灵活敏捷，如八面～～”此词现多形容为人处世手腕圆滑，面面俱到）。～琅。～玎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-玲"},{"id":"glyph-seal-73ba","script":"seal","character":"玺","reading":"xǐ","description":"印章；秦以后主要用来称帝王的印。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-73c2","script":"seal","character":"珂","reading":"kē","description":"kē：(1)玉名鸣～。～雪（形容洁白如雪）。\n(2)马笼头的装饰玉～。～月。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珂"},{"id":"glyph-seal-73c8","script":"seal","character":"珈","reading":"jiā","description":"jiā：古代妇女的一种头饰，用头发编成假髻，称副”；再用簪子把副别在头上，上加玉饰，称珈”；珈数多少有表明身份的作用，如六珈”为侯伯夫人所用。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珈"},{"id":"glyph-seal-73c9","script":"seal","character":"珉","reading":"mín","description":"mín：像玉的石头～玉（玉石）。～之雕雕，不若玉之章章”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珉"},{"id":"glyph-seal-73ca","script":"seal","character":"珊","reading":"shān","description":"shān：〔～瑚〕由一种叫珊瑚虫的腔肠动物的外骨骼聚集而成。用珊瑚”喻珍奇之物或人才，如铁网～～”（喻搜罗珍奇之物或人才）。\n〔～～〕a.形容衣裙玉佩的声音；b.摇曳多姿的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珊"},{"id":"glyph-seal-73cd","script":"seal","character":"珍","reading":"zhēn","description":"zhēn：(1)珠玉等宝物～宝。～珠。奇～异宝。席～待聘（席珍”，坐席上的宝石，喻怀才待用）。\n(2)宝贵的，贵重的～贵。～奇。～稀。～闻。～玩（贵重的供赏玩的东西）。\n(3)重视，爱惜～视。～爱。～重（zhòng）。～存。～藏（cáng）。\n(4)精美的食物～羞（亦作珍馐”）。八～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珍"},{"id":"glyph-seal-73d1","script":"seal","character":"珑","reading":"lóng","description":"振玉之声\n珑璁\n珑玲","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珑"},{"id":"glyph-seal-73d9","script":"seal","character":"珙","reading":"gǒng","description":"gǒng：古代玉器，大璧。\n〔～桐〕落叶乔木，茎高二十米左右，亦称空桐树”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珙"},{"id":"glyph-seal-73e0","script":"seal","character":"珠","reading":"zhū","description":"zhū：(1)蛤蚌因沙粒窜入壳内受到刺激而分泌的物质，逐层包起来形成圆粒，乳白色或略带黄色，有光泽，可做装饰品，亦可入药。称珍珠”（亦作真珠”，简称珠”）～蚌。～宝。～花。夜明～。～玑（喻优美的词藻或诗文）。～联璧合（珍珠联成串，美玉放在一起，喻人才或美好的事物聚集在一起）。\n(2)像珠子的东西汗～。泪～。露～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珠"},{"id":"glyph-seal-73e3","script":"seal","character":"珣","reading":"xún","description":"xún：玉名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珣"},{"id":"glyph-seal-73e5","script":"seal","character":"珥","reading":"ěr","description":"ěr：(1)用珠子或玉石做的耳环。\n(2)剑柄上端像两耳的突出部分。\n(3)插戴～笔（古代史官、谏官入朝插笔于冠侧，以便随时记录、写作）。～貂。\n(4)日、月两旁的光晕日～。月～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珥"},{"id":"glyph-seal-73e7","script":"seal","character":"珧","reading":"yáo","description":"yáo：蚌蛤的甲壳，古代用作刀、弓上的装饰品。\n〔江～〕软体动物，肉柱称江珧柱”，干制后又称干贝”，是珍贵的海味品。亦称玉珧”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珧"},{"id":"glyph-seal-73e9","script":"seal","character":"珩","reading":"héng","description":"héng：佩玉上面的横玉，形状像磬。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珩"},{"id":"glyph-seal-73ed","script":"seal","character":"班","reading":"bān","description":"bān：(1)一群人按次序排成的行列排～。按部就～。\n(2)工作或学习的组织～组。～级。～长。～主任。领～。\n(3)军队编制中的基层单位，在排”以下。\n(4)工作按时间分成的段落，亦指工作场所早～。下～。值～。～房。\n(5)定时开行（xíng）的～车。～机。～期。\n(6)量词（a.用于人群，如这～人真能干”；b.用于定时开行的交通运输工具，如他搭下一～飞机走”）。\n(7)调回或调动（军队）～师。～兵。\n(8)古同斑”，杂色。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-班"},{"id":"glyph-seal-73f0","script":"seal","character":"珰","reading":"dāng","description":"珰dāng 1.古代妇女的耳饰。 2.借指宦官『代宦官充武职者，其冠用珰和貂尾为饰，故后代用称宦官。 3.瓦当。屋椽头的装饰。 4.见\"珰琅\"﹑\"珰珰\"。 5.见\"琅珰\"","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-珰"},{"id":"glyph-seal-7403","script":"seal","character":"球","reading":"qiú","description":"qiú：(1)圆形的立体物圆～。～茎。～体。气～。煤～。\n(2)指球形的体育用品，球类运动～艺。～员。～坛。～迷。\n(3)星体，特指地球”月～。星～。誉满全～。\n(4)美玉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-球"},{"id":"glyph-seal-7405","script":"seal","character":"琅","reading":"láng","description":"láng：〔～～〕a.象声词，金石相击声；b.象声词，响亮的读书声，如书声～～”。\n〔～玕〕像珠子的美石。\n〔～玡〕山名，在中国山东省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琅"},{"id":"glyph-seal-7406","script":"seal","character":"理","reading":"lǐ","description":"lǐ：(1)物质本身的纹路、层次，客观事物本身的次序心～。肌～。条～。事～。\n(2)事物的规律，是非得失的标准，根据～由。～性。～智。～论。～喻。～解。～想。道～。～直气壮。\n(3)自然科学，有时特指物理学”～科，数～化。～疗。\n(4)按事物本身的规律或依据一定的标准对事物进行加工、处置～财。～事。管～。自～。修～。总～。\n(5)对别人的言行作出反应～睬。答～。\n(6)古代指狱官、法官。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-理"},{"id":"glyph-seal-7410","script":"seal","character":"琐","reading":"suǒ","description":"也作琐琐”\n镂玉为连环叫琐,后以金属为之,作锁”。连环;锁链\n锁链形的纹饰\n加在门、箱等上面使人不能随便开启的器具◇作锁”\n锁,铁锁\n⒈玉声。\n⒉微小，零碎～事。～碎。繁～。\n⒊连环连～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琐"},{"id":"glyph-seal-741a","script":"seal","character":"琚","reading":"jū；jv","description":"jū：古人佩带的玉琼～。华～（精美的玉佩）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琚"},{"id":"glyph-seal-741b","script":"seal","character":"琛","reading":"chēn","description":"chēn：珍宝～宝。天～（天然的宝物）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琛"},{"id":"glyph-seal-7422","script":"seal","character":"琢","reading":"zhuó；zuó","description":"zhuó：雕刻玉石，使成器物，常喻用心推敲考虑、刻意求工～磨。雕～（a.雕刻玉石等；b.过分地修饰文字，使人觉得不自然，如～～之风不可长”）。～刻。～句。玉不～，不成器。\nzuó：〔～磨〕思索、考虑，如他的话我～～了很久，不明白什么意思”（磨”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琢"},{"id":"glyph-seal-7424","script":"seal","character":"琤","reading":"jùn；chēng","description":"chēng：〔～～〕象声词，玉器相击声，琴声或水流声。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琤"},{"id":"glyph-seal-7425","script":"seal","character":"琥","reading":"hǔ","description":"hǔ：雕刻成虎形的玉器。\n〔～珀〕黄褐色透明体，是古代松柏树脂落入地下所成的化石，可做香料及装饰品，亦可入药。亦作虎魄”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琥"},{"id":"glyph-seal-7428","script":"seal","character":"琨","reading":"kūn","description":"kūn：美玉～玉。瑶～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琨"},{"id":"glyph-seal-742b","script":"seal","character":"琫","reading":"tǐng；běng","description":"běng：古代刀鞘上端的装饰。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琫"},{"id":"glyph-seal-742c","script":"seal","character":"琬","reading":"wǎn","description":"wǎn：没有棱角的圭～圭。～琰。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琬"},{"id":"glyph-seal-742e","script":"seal","character":"琮","reading":"cóng","description":"cóng：古代一种玉器，外边八角，中间圆形，常用作祭地的礼器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琮"},{"id":"glyph-seal-742f","script":"seal","character":"琯","reading":"gùn；guǎn","description":"guǎn：古代管乐器，用玉制成，像笛，六孔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琯"},{"id":"glyph-seal-7430","script":"seal","character":"琰","reading":"yǎn","description":"yǎn：美玉。\n〔～圭〕上端尖的圭。\n〔～～〕有光泽的样子，如黛玄眉之～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琰"},{"id":"glyph-seal-7433","script":"seal","character":"琳","reading":"lín","description":"lín：美玉～珉。～琅（a.美玉，喻美好珍贵的东西，如～～满目”；b.玉石发出的声音）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琳"},{"id":"glyph-seal-7434","script":"seal","character":"琴","reading":"qín","description":"qín：(1)古代弦乐器，最初是五根弦，后加至七根弦（亦称七弦琴”；通称古琴”）～瑟。～曲。～师。～意。抚～。～棋书画。\n(2)某些乐器的统称钢～。月～→～。口～。竖～。小提～。～书（曲艺的一种）。弹（tán）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琴"},{"id":"glyph-seal-7435","script":"seal","character":"琵","reading":"pí","description":"pí：〔～琶〕弦乐器（琶”读轻声）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琵"},{"id":"glyph-seal-7436","script":"seal","character":"琶","reading":"pá","description":"pá：〔琵～〕见琵”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琶"},{"id":"glyph-seal-743c","script":"seal","character":"琼","reading":"qióng","description":"博具,相当于后来的骰子\n比喻雪\n⒈美玉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-琼"},{"id":"glyph-seal-7441","script":"seal","character":"瑁","reading":"mào","description":"mào：古代帝王所执的玉器，用以覆诸侯的圭。\n〔玳～〕见玳”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑁"},{"id":"glyph-seal-7444","script":"seal","character":"瑄","reading":"xuān","description":"瑄xuān〈古〉用于祭天的璧。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑄"},{"id":"glyph-seal-7455","script":"seal","character":"瑕","reading":"xiá","description":"xiá：(1)玉上面的斑点，喻缺点或过失～玷。～垢。～疵。\n(2)空隙～隙。～衅（漏洞，可乘之隙；亦喻过错）。\n(3)古同霞”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑕"},{"id":"glyph-seal-7457","script":"seal","character":"瑗","reading":"yuàn","description":"yuàn：大孔的璧。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑗"},{"id":"glyph-seal-745a","script":"seal","character":"瑚","reading":"hú","description":"hú：〔～琏〕古代盛黍稷的祭器，用以喻人有立朝执政的才能。\n〔珊～〕见珊”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑚"},{"id":"glyph-seal-745b","script":"seal","character":"瑛","reading":"yīng","description":"yīng：(1)玉的光彩玉有～华（古籍中瑛”多作英”）。\n(2)像玉的美石～瑶。琼～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑛"},{"id":"glyph-seal-745c","script":"seal","character":"瑜","reading":"yú","description":"yú：(1)美玉。\n(2)玉的光泽，喻优点瑕～互见。瑕不掩～。\n〔～伽〕a.大乘佛教的派别之一，称瑜伽宗”；b.印度哲学的一派，此派注重调息、静坐等修行方法。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑜"},{"id":"glyph-seal-745e","script":"seal","character":"瑞","reading":"ruì","description":"ruì：(1)古代作为凭信的玉器～玉（诸侯朝见帝王时所执玉器的统称）。～节。～符。\n(2)吉详，好预兆～气。～芝。～签。～雨。祥～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑞"},{"id":"glyph-seal-745f","script":"seal","character":"瑟","reading":"sè","description":"sè：(1)弦乐器，似琴。长近三米，古有五十根弦，后为二十五根或十六根弦，平放演奏鼓～。\n(2)矜持端庄的样子。\n(3)洁净鲜明的样子。\n〔～～〕a.形容轻微的声音；b.形容颤抖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑟"},{"id":"glyph-seal-7470","script":"seal","character":"瑰","reading":"guī","description":"guī：(1)珍奇～异。～丽。～奇。～宝。～玮。～岸。～意琦行（赞颂卓越超人的思想和行为）。\n(2)次于玉的石头。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑰"},{"id":"glyph-seal-7476","script":"seal","character":"瑶","reading":"yáo","description":"yáo：(1)美玉，喻美好，珍贵，光明洁白琼～。～英。～宫。～琴。～浆。～觞。～台。～林琼树（喻人品格高洁）。～池。\n(2)中国少数民族，主要分布于广西壮族自治区和湖南、云南、广东、贵州等省～族。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑶"},{"id":"glyph-seal-747e","script":"seal","character":"瑾","reading":"jǐn","description":"jǐn：美玉，亦喻美德～瑜。怀～握瑜兮，穷不得所示”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瑾"},{"id":"glyph-seal-7480","script":"seal","character":"璀","reading":"cuǐ","description":"cuǐ：〔～璨〕形容珠玉的光泽。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璀"},{"id":"glyph-seal-7481","script":"seal","character":"璁","reading":"cōng","description":"cōng：〔～珑〕明亮光洁的样子。\n〔～琤〕玉声。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璁"},{"id":"glyph-seal-7487","script":"seal","character":"璇","reading":"xuán","description":"xuán：美玉～宫（旧指帝王后妃住处）。～玑（a.古代天文仪器；b.古代称北斗星的第一星至第四星）。～闺（旧指华丽的闺房）。～室。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璇"},{"id":"glyph-seal-748b","script":"seal","character":"璋","reading":"zhāng","description":"zhāng：古代的一种玉器，形状像半个圭圭～。弄～（旧时称生男孩）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璋"},{"id":"glyph-seal-7490","script":"seal","character":"璐","reading":"lù","description":"lù：美玉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璐"},{"id":"glyph-seal-749c","script":"seal","character":"璜","reading":"huáng","description":"huáng：半璧形的玉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璜"},{"id":"glyph-seal-74a0","script":"seal","character":"璠","reading":"fán","description":"fán：美玉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璠"},{"id":"glyph-seal-74a7","script":"seal","character":"璧","reading":"bì","description":"bì：(1)平圆形中间有孔的玉，古代在典礼时用作礼器，亦可作饰物。\n(2)美玉的通称～人（即玉人”，指容貌秀美的人）。～日（像璧玉一样圆而亮的太阳）。～月。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璧"},{"id":"glyph-seal-74a8","script":"seal","character":"璨","reading":"càn","description":"càn：(1)美玉。\n(2)同粲”①。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璨"},{"id":"glyph-seal-74a9","script":"seal","character":"璩","reading":"qú","description":"qú：(1)古代的一种耳环。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璩"},{"id":"glyph-seal-74aa","script":"seal","character":"璪","reading":"zǎo","description":"⒈〈古〉用五彩丝线贯穿玉片做成的冕绳。\n⒉刻在玉上或画在衣服上的水藻花纹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-璪"},{"id":"glyph-seal-74d2","script":"seal","character":"瓒","reading":"zàn","description":"古代祭祀时用的玉勺子\n瓒zàn玉勺。〈古〉祭祀时舀酒的器具玉～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓒"},{"id":"glyph-seal-74d8","script":"seal","character":"瓘","reading":"guàn","description":"guàn：古代的一种玉器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓘"},{"id":"glyph-seal-74dc","script":"seal","character":"瓜","reading":"guā","description":"guā：蔓生植物，属葫芦科，果实可食西～。冬～。～蒂。～分（像切瓜一样分割，如～～天下”）。～葛。～代。～李（指嫌疑的境地）。～子儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓜"},{"id":"glyph-seal-74e0","script":"seal","character":"瓠","reading":"hù","description":"hù：〔～子〕a.一年生草本植物，茎蔓生，夏天开白花，果实长圆形，嫩时可食；b.这种植物的果实。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓠"},{"id":"glyph-seal-74e2","script":"seal","character":"瓢","reading":"piáo","description":"piáo：(1)舀水或取东西的工具，多用对半剖开的匏瓜或木头制成～泼大雨。\n(2)形状像瓢的～虫。～儿菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓢"},{"id":"glyph-seal-74e3","script":"seal","character":"瓣","reading":"bàn","description":"bàn：(1)组成花冠的各片花～。\n(2)植物的种子、果实或球茎可以分开的片状物豆～儿。蒜～儿。\n(3)物体破裂分成的部分。\n(4)量词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓣"},{"id":"glyph-seal-74e6","script":"seal","character":"瓦","reading":"wǎ；wà","description":"wǎ：(1)用陶土烧成的～罐。～器。～釜雷鸣（喻无德无才的人占据高位，煊赫一时）。\n(2)用陶土烧成的覆盖房顶的东西～当（dāng）（即瓦筒之头）。～匠。\n〔～特〕电的功率单位。简称瓦”。\nwà：盖瓦这间房就等～瓦（wǎ）了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓦"},{"id":"glyph-seal-74ee","script":"seal","character":"瓮","reading":"wèng","description":"罋,瓶也。\n按,瓶”是汲水器,不是今天的所谓瓶\n汲水罐\n盛酒浆的坛\n大水缸","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓮"},{"id":"glyph-seal-74ef","script":"seal","character":"瓯","reading":"ōu","description":"杯;盅\n古代地名\n古水名,即永宁江,今称瓯江\n⒈小盆。\n⒉杯子茶～。\n⒊瓯江，在浙江省。\n瓯ǒu 1.古代部落名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓯"},{"id":"glyph-seal-74f4","script":"seal","character":"瓴","reading":"líng","description":"líng：(1)古代一种盛水的瓶子高屋建～（从房顶上往下泻水，喻居高临下的形势）。\n(2)房屋上仰盖的瓦，亦称瓦沟”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓴"},{"id":"glyph-seal-74f6","script":"seal","character":"瓶","reading":"píng","description":"píng：(1)口小腹大的器皿，多为瓷或玻璃做成，通常用来盛液体～子。酒～。花～。\n(2)量词，用于瓶装的东西两～啤酒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓶"},{"id":"glyph-seal-74f7","script":"seal","character":"瓷","reading":"cí","description":"cí：用高岭土烧成的一种质料，所做器物比陶器细致而坚硬陶～。～瓶。～壶。～碗。～器。～砖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓷"},{"id":"glyph-seal-74ff","script":"seal","character":"瓿","reading":"bù","description":"bù：古代的一种小瓮，青铜或陶制，用以盛酒或水。\n〔～畆〕小瓮，圆口，深腹，圈足，用以盛物。简称瓿”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瓿"},{"id":"glyph-seal-7504","script":"seal","character":"甄","reading":"zhēn","description":"zhēn：(1)审查，鉴别～审。～别。～选。～录（选择录用）。～品（鉴别品评）。～拔（甄别人材而荐举使用）。\n(2)制造陶器的转轮；制造陶器～陶（引申为对人的陶冶和造就）。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甄"},{"id":"glyph-seal-750d","script":"seal","character":"甍","reading":"méng","description":"méng：屋脊～宇齐平”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甍"},{"id":"glyph-seal-7511","script":"seal","character":"甑","reading":"zèng","description":"zèng：(1)古代蒸饭的一种瓦器。底部有许多透蒸气的孔格，置于鬲上蒸煮，如同现代的蒸锅～尘釜鱼。\n(2)蒸馏或使物体分解用的器皿曲颈～。\n〔～子〕现在蒸饭用的木制桶状物，有屉而无底。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甑"},{"id":"glyph-seal-7518","script":"seal","character":"甘","reading":"gān","description":"gān：(1)甜，味道好～甜。～苦。～冽。～落。～之如饴。同～共苦。～旨（美味的食物）。\n(2)美好～雨（适时而有益于农事的雨）。～霖。\n(3)自愿，乐意～愿。～拜下风。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甘"},{"id":"glyph-seal-751a","script":"seal","character":"甚","reading":"shèn；shén","description":"shèn：(1)很，极～好。～快。\n(2)超过日～一日。\n(3)方言，什么～事？\n(4)表示进一层的意思～至。～或。\nshén：同什2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甚"},{"id":"glyph-seal-751c","script":"seal","character":"甜","reading":"tián","description":"tián：像糖或蜜的滋味，喻使人感到舒服的，与苦”相对～品。～食。～菜。～瓜。～美。～润。～适。～爽。～言蜜语。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甜"},{"id":"glyph-seal-751f","script":"seal","character":"生","reading":"shēng","description":"shēng：(1)一切可以发育的物体在一定条件下具有了最初的体积和重量，并能发展长大诞～。滋～。～长。\n(2)造出～产。\n(3)活的，有活力的～存。～命。～物。～机。出～入死。舍～取义。\n(4)有生命的东西的简称众～。丧～。卫～。\n(5)生活，维持生活的～计。～意。\n(6)整个生活阶段一～。平～。今～。\n(7)发出，起动～病。～气。～效。～花之笔。谈笑风～。\n(8)使燃料燃烧起来～火。\n(9)植物果实不成熟～瓜。\n(10)未经烧煮或未烧煮熟的～饭。～水。\n(11)不熟悉的，不常见的～疏。～客。～字。陌～。\n(12)不熟练的～手。\n(13)未经炼制的。～铁。\n(14)硬态度～硬。～吞活剥。\n(15)甚，深～怕。～疼。\n(16)正在学习的人学～。门～。\n(17)有学问或有专业知识的人儒～。医～。\n(18)传统戏剧里扮演男子的角色小～。老～。武～。\n(19)词尾好～休养。\n(20)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-生"},{"id":"glyph-seal-7525","script":"seal","character":"甥","reading":"shēng","description":"shēng：〔外～〕姐妹的儿子，简作甥”，如～舅”。\n〔外～女〕姐妹的女儿，简作甥女”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甥"},{"id":"glyph-seal-7528","script":"seal","character":"用","reading":"yòng","description":"yòng：(1)使人或物发挥其功能使～。～心。～兵。～武。\n(2)可供使用的～品。～具。\n(3)进饭食的婉辞～饭。\n(4)花费的钱财费～。～项。～资。\n(5)物质使用的效果功～。有～之才。\n(6)需要（多为否定）不～多说。\n(7)因此～此。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-用"},{"id":"glyph-seal-752b","script":"seal","character":"甫","reading":"fǔ","description":"fǔ：(1)古代在男子名字下加的美称，后指人的表字（亦作父”）台～（询问别人名号的礼貌用语）。\n(2)刚刚，才年～弱冠。惊魂～定。\n(3)大无田～田”（不要去耕大田）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甫"},{"id":"glyph-seal-752c","script":"seal","character":"甬","reading":"yǒng","description":"yǒng：(1)中国浙江省宁波市的别称～剧（流行于宁波一带的地方戏曲剧种）。\n(2)钟柄。\n(3)花蓓蕾的样子草木花～～然。\n(4)古同桶”，古量器名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甬"},{"id":"glyph-seal-7530","script":"seal","character":"田","reading":"tián","description":"tián：(1)种植农作物的土地～野。耕～。\n(2)和农业有关的～家。～园。\n(3)古同畋”，打猎。\n(4)古同佃”，耕作。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-田"},{"id":"glyph-seal-7531","script":"seal","character":"由","reading":"yóu","description":"yóu：(1)原因原～。事～。理～。～于（介词，表示原因或理由）。\n(2)自，从～表及里。～衷（出于本心）。\n(3)顺随，听从，归属～不得。信马～缰。\n(4)经过，经历必～之路。～来已久。\n(5)凭借～此可知。\n(6)古同犹”，尚且，还。\n(7)古同犹”，犹如，好像。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-由"},{"id":"glyph-seal-7532","script":"seal","character":"甲","reading":"jiǎ","description":"jiǎ：(1)天干的第一位，用于作顺序第一的代称～子。花～（六十岁的人）。\n(2)居于首位的，超过所有其它的～等。\n(3)古代科举考试成绩名次的分类一～（名为进士及第”）；二～（名为进士出身”）；三～（名为同进士出身”）。\n(4)古代军人打仗穿的护身衣服，用皮革或金属叶片制成盔～。～兵。～士。\n(5)现代用金属做成有保护功能的装备～板。装～车。\n(6)某些动物身上有保护功能的硬壳龟～。\n(7)手指或脚趾上的角质硬壳指～。\n(8)旧时户口编制单位保～。～长。\n(9)植物果实的外壳～坼（外表裂开）。\n(10)古同胛”，肩胛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甲"},{"id":"glyph-seal-7533","script":"seal","character":"申","reading":"shēn","description":"shēn：(1)地支的第九位，属猴。\n(2)用于记时～时（下午三点至五点）。\n(3)陈述，说明～述。～斥。～辩。～冤。三令五～。～请。～报。\n(4)重复，一再～之以盟誓，重之以昏姻”。\n(5)中国上海市的别称。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-申"},{"id":"glyph-seal-7535","script":"seal","character":"电","reading":"diàn","description":",其光曰电。”\n物理学名词","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-电"},{"id":"glyph-seal-7537","script":"seal","character":"男","reading":"nán","description":"nán：(1)阳性的人～性。～人。～孩。～女平等。\n(2)儿子长（zhǎng）～。\n(3)封建制度五等爵位的第五等～爵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-男"},{"id":"glyph-seal-7538","script":"seal","character":"甸","reading":"diàn；tián；shèng","description":"diàn：(1)古代指郊外的地方。\n(2)田野的出产物纳货贝于君，则曰纳～于有司”。\n(3)治理。\ntián：古同畋”，打猎。\nshèng：古同乘”，古代划分田、里的名称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甸"},{"id":"glyph-seal-753a","script":"seal","character":"町","reading":"dīng；tǐng","description":"tǐng：田界田间小路～畦（田埂，喻界限、规矩、约束）。～疃（田舍旁的空地）。\n〔～～〕平坦的样子。\ndīng：〔畹～〕见畹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-町"},{"id":"glyph-seal-753b","script":"seal","character":"画","reading":"huà","description":"绘画;作画\n善画者或兼\n⒈图图～儿。宣传～。连环～儿。\n⒉描绘，写描～。绘～。～图表。～人物。～个圈儿。叫你～押。\n⒊汉字的一笔叫\"一画\"\"札\"字是五画。\n⒋同\"划\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-画"},{"id":"glyph-seal-753e","script":"seal","character":"甾","reading":"zāi；zī","description":"zāi：(1)有机化合物的一类，广泛存在于动植物体内，胆固醇和多种激素都属于甾类化合物。\n(2)古同灾”，祸难。\nzī：古同淄”，水名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-甾"},{"id":"glyph-seal-7540","script":"seal","character":"畀","reading":"bì","description":"bì：给与投～豺虎。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畀"},{"id":"glyph-seal-754b","script":"seal","character":"畋","reading":"tián","description":"tián：(1)打猎。\n(2)古同佃”，耕种。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畋"},{"id":"glyph-seal-754c","script":"seal","character":"界","reading":"jiè","description":"jiè：(1)边境，一个区域的边限～石（标志地界的石碑或石块）。～标。～址。～线（ａ．两个地区分界的线；ｂ．不同事物的分界；ｃ．某些事物的边缘）。～限（ａ．不同事物的分界；ｂ．尽头处，限度）。地～。\n(2)范围眼～。世～。自然～。\n(3)按职业或性别等所划的人群范围教育～。科学～。各～人士。\n(4)指大自然中动物、植物、矿物等的最大的类别无机～。有机～。\n(5)地层系统分类的最高一级，相当于地质年代中的代”。界”以下为系”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-界"},{"id":"glyph-seal-754e","script":"seal","character":"畎","reading":"quǎn","description":"quǎn：田地中间的沟～渎。～亩（田间，田地）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畎"},{"id":"glyph-seal-754f","script":"seal","character":"畏","reading":"wèi","description":"wèi：(1)怕～惧。～难（nán）。～罪。大无～。望而生～。\n(2)敬服敬～。～友（使人敬服的朋友）◇生可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畏"},{"id":"glyph-seal-7554","script":"seal","character":"畔","reading":"pàn","description":"pàn：(1)田地的界限。\n(2)边河～〓～。桥～。耳～。枕～。\n(3)古同叛”。\n〔～援〕横暴，跋扈，如帝谓文王，无然～～。”亦称畔换”、叛换”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畔"},{"id":"glyph-seal-7559","script":"seal","character":"留","reading":"liú","description":"liú：(1)停止在某一个地方停～。～学。～任。～级。～步。～守。～驻。\n(2)注意力放在上面～心。～神。～意。\n(3)不忍舍弃，不忍离去～连。～恋。\n(4)不使离开～客。～宿。挽～。拘～。\n(5)接受收～。\n(6)保存保～。～存。～别。～念。～后路。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-留"},{"id":"glyph-seal-755a","script":"seal","character":"畚","reading":"běn","description":"běn：〔～箕〕用木、竹、铁片做成的撮垃圾、粮食等的器具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畚"},{"id":"glyph-seal-755b","script":"seal","character":"畛","reading":"zhěn","description":"zhěn：(1)田地间的小路。\n(2)界限～域。～畦（规定的范围，界限）。\n(3)致意，祝告～于鬼神”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畛"},{"id":"glyph-seal-755c","script":"seal","character":"畜","reading":"chù；xù","description":"xù：养禽兽～产。～牧。～养。\nchù：禽兽，有时专指家养的禽兽～肥。～力。～疫。幼～。牲～。家～。～生。六～兴旺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畜"},{"id":"glyph-seal-7565","script":"seal","character":"略","reading":"lüè","description":"lüè：(1)大致，简单，不详细大～。简～。粗～。～微。～有所闻。～知一二。\n(2)省去，简化省～■～。其余从～。\n(3)简要的叙述史～。要～。事～。\n(4)计谋方～。策～。战～。\n(5)抢，掠夺侵～。攻城～地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-略"},{"id":"glyph-seal-7566","script":"seal","character":"畦","reading":"qí","description":"qí：(1)田园中分成的小区～田。菜～。\n(2)古代称田五十亩为一畦。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畦"},{"id":"glyph-seal-756a","script":"seal","character":"番","reading":"fān；pān","description":"fān：(1)遍数，次，回三～五次。\n(2)轮流更代轮～。更（gēng）～。\n(3)称外国的或外族的～邦。～茄。～薯。\n(4)倍产量翻了二～。\npān：〔～禺〕地名，在中国广东省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-番"},{"id":"glyph-seal-7574","script":"seal","character":"畴","reading":"chóu","description":"特指种麻的田\n同类,类别◇作俦”\n①田地田～、平～千里。\n②种类范～。\n⒈田地田～。\n⒉类，同类，类别范～。物各有～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畴"},{"id":"glyph-seal-7578","script":"seal","character":"畸","reading":"jī","description":"jī：(1)不规则的，不正常的～形。～胎。～人。～变。\n(2)残余，零星～数。～零。～羡（指剩余）。\n(3)偏～轻～重。\n(4)古同奇”，数目不成双的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畸"},{"id":"glyph-seal-7579","script":"seal","character":"畹","reading":"wǎn","description":"wǎn：古代称三十亩地为畹。\n〔～町（dīng）〕地名，在中国云南省西部边境。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畹"},{"id":"glyph-seal-757f","script":"seal","character":"畿","reading":"jī","description":"jī：(1)古代称靠近国都的地方～辅。～辇。京～。\n(2)门限，门槛。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-畿"},{"id":"glyph-seal-7583","script":"seal","character":"疃","reading":"tuǎn","description":"tuǎn：(1)禽兽践踏的地方，\n(2)村庄，屯（多用于地名）白家～（在中国北京市）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疃"},{"id":"glyph-seal-7586","script":"seal","character":"疆","reading":"jiāng；qiáng","description":"jiāng：(1)地域，领域，边界～土。～宇（国土）。～界。～场（战场）。～陲（边境）。边～。～。\n(2)极限万寿无～。\n(3)划分界限楚子～之”。\nqiáng：古同彊（强）”，强大。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疆"},{"id":"glyph-seal-758f","script":"seal","character":"疏","reading":"shū","description":"shū：(1)去掉阻塞使通畅～导。～通。～浚。～解（jiě）。\n(2)分散～散。仗义～财。\n(3)事物间距离大，空隙大，与密”相对～密。～松。～朗。～旷。～阔。～落（luò）。稀～。天网恢恢，～而不漏。\n(4)不亲密，关系远的亲～。～远。\n(5)不细密，忽略～忽。\n(6)空虚志大才～。\n(7)不熟悉生～。\n(8)粗劣～食。～粝。\n(9)古同蔬”，蔬菜。\n(10)分条说明的文字上～（臣子向帝王分条陈述的意见书）。奏～。注～（对古书的注解和对注解的注释）。\n(11)僧道拜忏时所焚化的祝告文。\n(12)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疏"},{"id":"glyph-seal-7591","script":"seal","character":"疑","reading":"yí；nǐ","description":"yí：(1)不信，猜度（duó）～惑。～问。～心。～团。～虑。～窦。～点。～端。猜～。怀～。半信半～。\n(2)不能解决的，不能断定的～案。～难。～义。存～。\n信；\nnǐ：(1)安定，止息。\n(2)古同拟”，比拟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疑"},{"id":"glyph-seal-7597","script":"seal","character":"疗","reading":"liáo","description":"治愈,治好;止","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疗"},{"id":"glyph-seal-759d","script":"seal","character":"疝","reading":"shàn","description":"shàn：病，某一脏器通过周围组织较薄弱的地方而隆起～气（通常指腹股沟部的疝。亦称小肠串气”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疝"},{"id":"glyph-seal-759f","script":"seal","character":"疟","reading":"nüè","description":"通虐”。残暴;灾害\n受虐待\n义同疟”,只用于疟子”\n～、三日～、恶性～等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疟"},{"id":"glyph-seal-75a0","script":"seal","character":"疠","reading":"lì","description":"恶疮;麻风\n疫病 ［pestilence］\n⒈瘟疫～疾。\n⒉恶疮疥～。\n⒊〈古〉同\"癩\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疠"},{"id":"glyph-seal-75a1","script":"seal","character":"疡","reading":"yáng","description":"破损,溃烂\n⒈疮。\n⒉皮肤或粘膜溃烂所造成的缺损溃～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疡"},{"id":"glyph-seal-75a3","script":"seal","character":"疣","reading":"yóu","description":"yóu：一种皮肤病，病原体是一种病毒，症状是皮肤上出现黄褐色的小疙瘩，不痛也不痒（俗称瘊子”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疣"},{"id":"glyph-seal-75a5","script":"seal","character":"疥","reading":"jiè","description":"jiè：一种传染性皮肤病，非常剌痒，是疥虫寄生而引起的。通常称疥疮”，亦称疥癣”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疥"},{"id":"glyph-seal-75ab","script":"seal","character":"疫","reading":"yì","description":"yì：流行性急性传染病瘟～。鼠～。防～。检～。～情。免～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疫"},{"id":"glyph-seal-75ad","script":"seal","character":"疭","reading":"zòng","description":"见“瘛疭”，中医指手足痉挛、抽搐的症状。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-75b1","script":"seal","character":"疱","reading":"pào","description":"pào：皮肤上长的像水泡的小疙瘩（亦作泡”）水～。火～。脓～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疱"},{"id":"glyph-seal-75b2","script":"seal","character":"疲","reading":"pí","description":"pí：(1)身体劳累的感觉～乏。～倦。～劳。～惫。～敝。精～力尽。\n(2)懈怠，不起劲～塌。～软。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疲"},{"id":"glyph-seal-75b4","script":"seal","character":"疴","reading":"kē","description":"kē：病沉～（重病）。染～。养～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疴"},{"id":"glyph-seal-75b5","script":"seal","character":"疵","reading":"cī","description":"cī：(1)毛病～吝。～病。吹毛求～。\n(2)缺点或过失～瑕。～咎。～点。\n(3)诽谤，非议～物。～毁。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疵"},{"id":"glyph-seal-75b8","script":"seal","character":"疸","reading":"da；dǎn","description":"dǎn：〔黄～〕病名，病人的皮肤、黏膜和眼球的巩膜等都呈黄色，是由胆汁的胆红素大量出现在血液中所引起。亦作黄病”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疸"},{"id":"glyph-seal-75b9","script":"seal","character":"疹","reading":"zhěn","description":"zhěn：皮肤上起的小颗粒，通常是红色，多由皮肤表层发炎浸润而起湿～。麻～（亦称疹子”）。风～。丘～。疱～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疹"},{"id":"glyph-seal-75bd","script":"seal","character":"疽","reading":"jū；jv","description":"jū：中医指一种毒疮痈～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疽"},{"id":"glyph-seal-75be","script":"seal","character":"疾","reading":"jí","description":"jí：(1)病，身体不舒适～病。目～。残～。讳～忌医。\n(2)一般的痛苦～苦。\n(3)疼痛～首蹙额。\n(4)恨～恶如仇。\n(5)古同嫉”，妒忌。\n(6)弊病，缺点寡人有～”。\n(7)快，迅速～步。～走。～进。～驰。～足先得。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-疾"},{"id":"glyph-seal-75c2","script":"seal","character":"痂","reading":"jiā","description":"jiā：伤口或疮口血液、淋巴液等凝结成的东西，伤口或疮口痊愈后，自行脱落结～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痂"},{"id":"glyph-seal-75c5","script":"seal","character":"病","reading":"bìng","description":"bìng：(1)生物体发生不健康的现象疾～。～症。～例。～痛。～情。～源。～愈。～变。～危。～逝。～榻。～残。\n(2)缺点，错误语～。通～。弊～。\n(3)损害，祸害祸国～民。\n(4)不满，责备诟～。\n(5)烦躁，担忧郑人～之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-病"},{"id":"glyph-seal-75c8","script":"seal","character":"痈","reading":"yōng","description":"鼻疾,不知香臭\n喻祸患\n口疮\"。背痈俗称\"搭背\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痈"},{"id":"glyph-seal-75c9","script":"seal","character":"痉","reading":"jìng","description":"风强病。也称痉挛”\n痉挛\n痉笑","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痉"},{"id":"glyph-seal-75cd","script":"seal","character":"痍","reading":"yí","description":"yí：伤，创伤疮～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痍"},{"id":"glyph-seal-75d2","script":"seal","character":"痒","reading":"yǎng","description":"形容某些难以抑制的强烈愿望\n痒yáng 1.忧思过度所成之病。 2.受损害;损害。 3.通\"疡\"。痈疮。参见\"痒疥\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痒"},{"id":"glyph-seal-75d4","script":"seal","character":"痔","reading":"zhì","description":"zhì：肛门因血行障碍而引起的一种病～疮。～漏（肛瘘的通称）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痔"},{"id":"glyph-seal-75d5","script":"seal","character":"痕","reading":"hén","description":"hén：创伤痊愈后留下的疤，亦泛指斑迹～印。～迹。～瘕（疤痕。喻曾犯有罪案的人）。伤～。泪～。裂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痕"},{"id":"glyph-seal-75db","script":"seal","character":"痛","reading":"tòng","description":"tòng：(1)疾病、创伤等引起的难受的感觉头～。肚子～。～风。～痒（ａ．喻疾苦，如～～相关”；ｂ．喻紧要的事，如不关～～”）。\n(2)悲伤悲～。哀～。～楚。～惜。～不欲生。\n(3)尽情地，深切地，彻底地～击。～悼。～责。～快。～改前非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痛"},{"id":"glyph-seal-75de","script":"seal","character":"痞","reading":"pǐ","description":"pǐ：(1)中医指胸腹间气机阻塞不舒的一种自觉症状，有的仅有胀满的感觉，称痞块”、痞积”。\n(2)恶棍，流氓～子。地～。文～。～里～气。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痞"},{"id":"glyph-seal-75e4","script":"seal","character":"痤","reading":"cuó","description":"cuó：痈～疽（即痈疽”）。\n〔～疮〕一种皮肤病，俗称粉剌”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痤"},{"id":"glyph-seal-75e8","script":"seal","character":"痨","reading":"láo","description":"劳损病\n结核病的俗称。多指肺结核\n痨病","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痨"},{"id":"glyph-seal-75eb","script":"seal","character":"痫","reading":"xián","description":"俗称羊痫风、羊癫风、羊角风\n痫证","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痫"},{"id":"glyph-seal-75f1","script":"seal","character":"痱","reading":"fèi；féi","description":"fèi：〔～子〕由于暑天出汗过多，引起汗腺发炎，皮肤表面生出来的小红疹，很痒。\nféi：古代称偏瘫症风～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痱"},{"id":"glyph-seal-75f4","script":"seal","character":"痴","reading":"chī","description":"chī：(1)傻，无知～人说梦。～钝。～愚。白～。\n(2)精神失常，疯癫发～。～癫。\n(3)入迷，极度迷恋～心。～情。\n(4)谦辞，白白地～长（zhǎng）（说自己白白地比对方大若干岁）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痴"},{"id":"glyph-seal-75f9","script":"seal","character":"痹","reading":"bì","description":"bì：〔～症〕中医指由风、寒、湿等引起的肢体疼痛或麻木的病。\n〔麻～〕见麻”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痹"},{"id":"glyph-seal-75fc","script":"seal","character":"痼","reading":"gù","description":"gù：(1)经久难治愈的病～疾。\n(2)长期养成的不易克服的癖好、习惯～癖。～习。～弊。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痼"},{"id":"glyph-seal-75ff","script":"seal","character":"痿","reading":"wěi","description":"wěi：身体某部分萎缩或失去机能的病下～。阳～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-痿"},{"id":"glyph-seal-7603","script":"seal","character":"瘃","reading":"zhú","description":"zhú：(1)病名，即冻疮”冻～。\n(2)冻干（gān）～脯（冻肉干）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘃"},{"id":"glyph-seal-760c","script":"seal","character":"瘌","reading":"là","description":"là：〔～痢〕生在人头上的皮肤病。亦称秃疮”。\n〔疤～〕见疤”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘌"},{"id":"glyph-seal-7618","script":"seal","character":"瘘","reading":"lòu","description":"颈肿大的病。即颈部淋巴结核\n瘘管\n瘘lǘ 1.佝偻，驼背。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘘"},{"id":"glyph-seal-761b","script":"seal","character":"瘛","reading":"chì","description":"chì：〔～痵〕中医指手脚痉挛，因歪眼斜的症状。亦称抽风”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘛"},{"id":"glyph-seal-7622","script":"seal","character":"瘢","reading":"bān","description":"bān：(1)疮痕，疤瘌，斑点刀～。疮～」～。雀～。\n(2)皮肤上的一点美玉可以减～。”\n(3)缺点或过失。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘢"},{"id":"glyph-seal-7624","script":"seal","character":"瘤","reading":"liú","description":"liú：身体组织增殖生成的赘生物，多由刺激或微生物寄生而起～子。肉～。肿～。根～。～胃（反刍动物的胃的一部分）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘤"},{"id":"glyph-seal-7626","script":"seal","character":"瘦","reading":"shòu","description":"shòu：(1)体内含脂肪少，肌肉不丰满，与胖”、肥”相对～溜（溜”读轻声）。～弱。～小。～削。～俏。～长（cháng）。～瘪。消～。清～。～骨嶙峋。\n(2)衣服鞋袜等窄小这条裤子太～了。\n(3)细削，单薄字小而～。\n(4)土地瘠薄～瘠。\n(5)遒劲有骨力书贵～硬。水清石～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘦"},{"id":"glyph-seal-7633","script":"seal","character":"瘳","reading":"chōu","description":"chōu：(1)病愈。\n(2)损害，减损。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘳"},{"id":"glyph-seal-7635","script":"seal","character":"瘵","reading":"zhai；zhài","description":"zhài：病，多指痨病痨～。病～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘵"},{"id":"glyph-seal-763c","script":"seal","character":"瘼","reading":"mò","description":"mò：病，疾苦民～（人民的痛苦）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘼"},{"id":"glyph-seal-763f","script":"seal","character":"瘿","reading":"yǐng","description":"虫瘿。树木外部隆起如瘤者\n指累赘,多余的东西\n⒈颈瘤。多指甲状腺肿。\n⒉树木上隆起像肿瘤的部分树～。\n⒊虫瘿，简称\"瘿\"。受虫害侵蚀的组织，发生变化所形成的瘤状物。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-瘿"},{"id":"glyph-seal-7643","script":"seal","character":"癃","reading":"lóng","description":"lóng：旧指年老衰弱多病。\n〔～闭〕中医指小便不通或淋沥点滴而出。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癃"},{"id":"glyph-seal-7663","script":"seal","character":"癣","reading":"xuǎn","description":"癣xuǎn感染霉菌后引起的皮肤病头～。脚～。花斑～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癣"},{"id":"glyph-seal-766f","script":"seal","character":"癯","reading":"qú","description":"qú：瘦清～。～瘦。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癯"},{"id":"glyph-seal-7678","script":"seal","character":"癸","reading":"guǐ","description":"guǐ：天干的第十位，用于作顺序第十的代称。\n〔～水〕指月经。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-癸"},{"id":"glyph-seal-767b","script":"seal","character":"登","reading":"dēng","description":"dēng：(1)上，升～山。～车。～门。～天。～台。～场（chǎng）。～高。～攀。～临。～科。～程。～堂入室。\n(2)踩，践踏，脚向下用力～踏。踢～。\n(3)记载～记。～报。～载。\n(4)谷物成熟～岁（丰年）。五谷丰～。\n(5)立刻～时。～即相许和，便可作婚姻。”\n(6)进～崇（进用推崇）。\n(7)方言，穿～上靴子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-登"},{"id":"glyph-seal-767d","script":"seal","character":"白","reading":"bái","description":"bái：(1)雪花或乳汁那样的颜色～色。～米。\n(2)明亮～昼。～日做梦。\n(3)清楚明～。不～之冤。\n(4)纯洁一生清～。～璧无瑕。\n(5)空的，没有加上其它东西的空～。～卷。\n(6)没有成就的，没有效果的～忙。～说。\n(7)没有付出代价的～吃～喝。\n(8)陈述自～。道～（亦称说白”、白口”）。\n(9)与文言相对～话文。\n(10)告语告～（对公众的通知）。\n(11)丧事红～喜事（婚事和丧事）。\n(12)把字写错或读错～字（别字）。\n(13)政治上反动的～匪。～军。\n(14)中国少数民族，主要分布于云南省～族。～剧。\n(15)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-白"},{"id":"glyph-seal-767e","script":"seal","character":"百","reading":"bǎi","description":"bǎi：(1)数名，十个十（在钞票和单据上常用大写佰”代）～步穿杨。～儿八十。～分比。\n(2)喻很多～草。～货。～姓（人民）。～般。～炼成钢。～无聊赖。～废俱兴（xīng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-百"},{"id":"glyph-seal-7686","script":"seal","character":"皆","reading":"jiē","description":"jiē：全，都～大欢喜。人人～知。放之四海而～准。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皆"},{"id":"glyph-seal-7687","script":"seal","character":"皇","reading":"huáng","description":"huáng：(1)君主，亦指神话传说中的神～帝。～后。～宫。～储（已确定的皇位继承人）。～权。\n(2)大～～巨著。冠冕堂～。\n(3)对先代的敬称～考（对亡父的尊称）。\n(4)古同遑”，闲遐。\n(5)古同惶”，恐惧。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皇"},{"id":"glyph-seal-768b","script":"seal","character":"皋","reading":"gāo；yáo","description":"gāo：(1)水边的高地，岸江～『～。\n(2)沼泽，湖泊鹤鸣于九～”。\nyáo：〔～陶〕中国上古人名，相传是舜臣。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皋"},{"id":"glyph-seal-768e","script":"seal","character":"皎","reading":"jiǎo","description":"jiǎo：(1)洁白，明亮～白。～洁（明亮洁白，如～～的月光”）。～月。～～。\n(2)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皎"},{"id":"glyph-seal-7691","script":"seal","character":"皑","reading":"ái","description":"洁白的样子，如白雪皑皑。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-7693","script":"seal","character":"皓","reading":"hào","description":"hào：(1)洁白，明亮～白。～齿。～首穷经。～月当空。\n(2)古同昊”，昊天。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皓"},{"id":"glyph-seal-7699","script":"seal","character":"皙","reading":"xī","description":"xī：(1)皮肤白其民～而瘠。”\n(2)泛指白色～帻而衣狸制。”\n(3)一种只开花，不结果的枣树。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皙"},{"id":"glyph-seal-76a4","script":"seal","character":"皤","reading":"pó","description":"pó：(1)形容白色白发～然。\n(2)大（腹）～其腹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皤"},{"id":"glyph-seal-76ae","script":"seal","character":"皮","reading":"pí","description":"pí：(1)动植物体表的一层组织～毛。\n(2)兽皮或皮毛的制成品裘～。\n(3)包在外面的一层东西封～。书～。\n(4)表面地～。\n(5)薄片状的东西豆腐～。\n(6)韧性大，不松脆花生放～了。\n(7)不老实，淘气顽～。\n(8)指橡胶胶～。～球。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皮"},{"id":"glyph-seal-76b2","script":"seal","character":"皲","reading":"jūn","description":"手足的皮肤冻裂\n皲裂\n皲jūn皮肤因寒冷或干燥而破裂。也作\"龟\"～裂。又指物体开裂田地～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皲"},{"id":"glyph-seal-76b4","script":"seal","character":"皴","reading":"cūn","description":"cūn：(1)皮肤因受冻或受风吹而干裂～裂。～理（裂纹）。\n(2)皮肤上积存的泥垢和脱落的表皮手上全是～。\n(3)中国画技法之一，涂出物体纹理或阴阳向背～法。～笔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皴"},{"id":"glyph-seal-76bf","script":"seal","character":"皿","reading":"mǐn","description":"mǐn：碗、碟、杯、盘一类用器的统称器～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-皿"},{"id":"glyph-seal-76c2","script":"seal","character":"盂","reading":"yú","description":"yú：一种盛液体的器皿水～。痰～。漱口～儿。\n〔～兰盆会〕每逢农历七月十五日（中元节）佛教徒为超度祖先亡灵所举行的仪式。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盂"},{"id":"glyph-seal-76c5","script":"seal","character":"盅","reading":"zhōng","description":"zhōng：饮酒或喝茶用的没有把儿的杯子酒～。茶～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-盅"}];
